import React, { useState, useMemo } from 'react';
import { 
  Card, 
  Table, 
  Button, 
  Input, 
  Select, 
  Space, 
  Tag, 
  Typography, 
  Row, 
  Col, 
  Statistic, 
  Pagination,
  message,
  Tooltip,
  Rate,
  Modal,
  Form,
  Dropdown
} from 'antd';
import { 
  SearchOutlined, 
  PlusOutlined,
  DownOutlined,
  QuestionCircleOutlined,
  HistoryOutlined,
  ShareAltOutlined,
  LinkOutlined,
  FileTextOutlined,
  BookOutlined
} from '@ant-design/icons';
import { useNavigate, useLocation } from 'umi';
import { mockCustomerHandovers } from '../../mock/handoverData';
import { CustomerHandover, HandoverStatus, RiskLevel, HandoverSearchParams } from '../../types/handover';
import type { InputRef } from 'antd';
import type { ColumnType } from 'antd/es/table';
import type { FilterConfirmProps } from 'antd/es/table/interface';
import { useRef } from 'react';

const { Title, Text } = Typography;
const { Option } = Select;

// 统一的卡片样式 - 参考工作看板的现代风格
const cardStyle = {
  borderRadius: '12px',
  boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06)',
  border: '1px solid #f0f0f0',
  background: '#ffffff',
  marginBottom: '16px',
};

const HandoverListPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);
  const pageSize = 5; // 一页显示5个数据

  // 搜索筛选状态
  const [searchText, setSearchText] = useState('');
  const [searchedColumn, setSearchedColumn] = useState('');
  const searchInput = useRef<InputRef>(null);

  const [searchParams, setSearchParams] = useState<HandoverSearchParams>({
    customerName: '',
    status: undefined,
    riskLevel: undefined
  });

  // 快链相关状态
  const [quickLinks, setQuickLinks] = useState([
    { id: 1, name: '实施资料', url: 'https://docs.example.com/implementation' },
    { id: 2, name: '用户手册', url: 'https://docs.example.com/user-manual' }
  ]);
  const [addLinkModalVisible, setAddLinkModalVisible] = useState(false);
  const [form] = Form.useForm();

  // 处理搜索
  const handleSearch = (
    selectedKeys: string[],
    confirm: (param?: FilterConfirmProps) => void,
    dataIndex: keyof CustomerHandover,
  ) => {
    confirm();
    setSearchText(selectedKeys[0]);
    setSearchedColumn(dataIndex);
  };

  // 处理重置
  const handleReset = (clearFilters: () => void) => {
    clearFilters();
    setSearchText('');
  };

  // 获取列搜索属性
  const getColumnSearchProps = (dataIndex: keyof CustomerHandover): ColumnType<CustomerHandover> => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters, close }) => (
      <div style={{ padding: 8 }} onKeyDown={e => e.stopPropagation()}>
        <Input
          ref={searchInput}
          placeholder={`搜索 ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => handleSearch(selectedKeys as string[], confirm, dataIndex)}
          style={{ marginBottom: 8, display: 'block' }}
        />
        <Space>
          <Button
            type="primary"
            onClick={() => handleSearch(selectedKeys as string[], confirm, dataIndex)}
            icon={<SearchOutlined />}
            size="small"
            style={{ width: 90 }}
          >
            搜索
          </Button>
          <Button
            onClick={() => clearFilters && handleReset(clearFilters)}
            size="small"
            style={{ width: 90 }}
          >
            重置
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              confirm({ closeDropdown: false });
              setSearchText((selectedKeys as string[])[0]);
              setSearchedColumn(dataIndex);
            }}
          >
            筛选
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              close();
            }}
          >
            关闭
          </Button>
        </Space>
      </div>
    ),
    filterIcon: (filtered: boolean) => (
      <SearchOutlined style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) => {
      const fieldValue = record[dataIndex];
      if (fieldValue === null || fieldValue === undefined) return false;
      return fieldValue
        .toString()
        .toLowerCase()
        .includes((value as string).toLowerCase());
    },
    onFilterDropdownOpenChange: visible => {
      if (visible) {
        setTimeout(() => searchInput.current?.select(), 100);
      }
    },
  });

  // 处理新增交接
  const handleAddHandover = () => {
    navigate('/profiles/handover/new');
  };



  // 处理分享
  const handleShare = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('请先选择要分享的交接单');
      return;
    }
    message.success(`已选择 ${selectedRowKeys.length} 个交接单进行分享`);
  };

  // 快链相关处理函数
  const handleQuickLinkClick = (url: string) => {
    window.open(url, '_blank');
  };

  const handleAddQuickLink = () => {
    setAddLinkModalVisible(true);
  };

  const handleAddLinkSubmit = async () => {
    try {
      const values = await form.validateFields();
      const newLink = {
        id: Date.now(),
        name: values.name,
        url: values.url
      };
      setQuickLinks([...quickLinks, newLink]);
      setAddLinkModalVisible(false);
      form.resetFields();
      message.success('快链添加成功');
    } catch (error) {
      console.error('表单验证失败:', error);
    }
  };

  const handleAddLinkCancel = () => {
    setAddLinkModalVisible(false);
    form.resetFields();
  };

  // 多选配置
  const rowSelection = {
    selectedRowKeys,
    onChange: (newSelectedRowKeys: React.Key[]) => {
      setSelectedRowKeys(newSelectedRowKeys);
    },
    onSelectAll: (selected: boolean, selectedRows: CustomerHandover[], changeRows: CustomerHandover[]) => {
      console.log(selected, selectedRows, changeRows);
    },
  };

  // 处理查看详情（可指定默认标签页）
  const handleViewDetail = (record: CustomerHandover, tabKey?: string) => {
    const url = tabKey ? `/profiles/handover/${record.id}?tab=${tabKey}` : `/profiles/handover/${record.id}`;
    navigate(url);
  };

  // 根据当前路径决定显示什么内容
  const pathname = location.pathname;


  // 如果是创建页面
  if (pathname === '/profiles/handover/new') {
    return (
      <div style={{ 
        padding: '24px',
        background: '#fafafa',
        minHeight: 'calc(100vh - 120px)',
        paddingBottom: '60px' // 为footer留出底部间距
      }}>
        <div style={{ 
          maxWidth: '1000px', 
          margin: '0 auto'
        }}>
          {/* 页面标题和返回按钮 */}
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            marginBottom: '24px',
            gap: '16px'
          }}>
            <Button 
              onClick={() => navigate('/profiles/handover-implementation')}
              style={{ border: 'none', padding: 0 }}
            >
              返回
            </Button>
            <Title level={3} style={{ margin: 0, color: '#262626', fontSize: '18px' }}>
              创建新客户交接
            </Title>
          </div>

          {/* 创建表单 */}
          <div style={{ 
            background: '#fff',
            borderRadius: '8px',
            padding: '24px'
          }}>
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <Title level={4} style={{ color: '#666' }}>
                创建客户交接表单
              </Title>
              <p style={{ color: '#999' }}>
                这里将显示创建客户交接的表单内容
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // 如果是详情页面或历史查询页面，不显示列表页内容
  if (pathname.match(/^\/profiles\/handover\/\d+$/) || pathname === '/profiles/handover/history') {
    return null;
  }

  // 过滤数据
  const filteredData = useMemo(() => {
    return mockCustomerHandovers.filter(item => {
      const text = (searchText || '').trim().toLowerCase();
      const matchText = !text || (item.customerName?.toLowerCase().includes(text) || item.handoverNumber?.toLowerCase().includes(text));
      const matchName = !searchParams.customerName || 
        item.customerName.includes(searchParams.customerName);
      const matchStatus = !searchParams.status || 
        item.handoverStatus === searchParams.status;
      const matchRisk = !searchParams.riskLevel || 
        item.riskLevel === searchParams.riskLevel;

      return matchText && matchName && matchStatus && matchRisk;
    });
  }, [searchParams, searchText]);

  // 分页数据
  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return filteredData.slice(startIndex, startIndex + pageSize);
  }, [filteredData, currentPage]);

  // 顶部数据看板统计
  const kpi = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();
    const toDate = (s: string) => new Date(s.replace(/-/g, '/'));

    const pendingCount = mockCustomerHandovers.length;
    const completedThisMonth = mockCustomerHandovers.filter(item => {
      if (item.expectationAlignment !== 'aligned') return false;
      const updated = toDate(item.updatedAt);
      return updated.getFullYear() === currentYear && updated.getMonth() === currentMonth;
    }).length;
    const riskyCount = mockCustomerHandovers.filter(item => item.hasRiskAlert).length;

    // 计算本月交接平均满意度（使用handoverRating字段）
    const thisMonthHandovers = mockCustomerHandovers.filter(item => {
      const updated = toDate(item.updatedAt);
      return updated.getFullYear() === currentYear && updated.getMonth() === currentMonth;
    });
    const avgSatisfaction = thisMonthHandovers.length > 0 
      ? (thisMonthHandovers.reduce((sum, item) => sum + (item.handoverRating || 0), 0) / thisMonthHandovers.length).toFixed(1)
      : '0.0';

    return { pendingCount, completedThisMonth, riskyCount, avgSatisfaction };
  }, []);

  // 状态标签颜色映射
  const statusColorMap = {
    pending: 'orange',
    processing: 'blue',
    aligned: 'green',
    partially_aligned: 'gold'
  };

  // 状态文本映射
  const statusTextMap = {
    pending: '待处理',
    processing: '处理中',
    aligned: '已对齐',
    partially_aligned: '部分对齐'
  };

  // 风险等级颜色映射
  const riskColorMap = {
    high: 'red',
    medium: 'orange',
    low: 'green'
  };

  // 风险等级文本映射
  const riskTextMap = {
    high: '高风险',
    medium: '中风险',
    low: '低风险'
  };

  // 表格列定义
  const columns = [
    {
      title: '交接单编号',
      dataIndex: 'handoverNumber',
      key: 'handoverNumber',
      width: 120,
      fixed: 'left' as const,
      render: (num: string, record: CustomerHandover) => (
        <span style={{ fontFamily: 'monospace' }}>{num}</span>
      ),
    },
    {
      title: '客户名称',
      dataIndex: 'customerName',
      key: 'customerName',
      width: 160,
      fixed: 'left' as const,
      sorter: (a: CustomerHandover, b: CustomerHandover) => a.customerName.localeCompare(b.customerName),
      render: (name: string, record: CustomerHandover) => (
        <a onClick={() => handleViewDetail(record, 'action-plan')}>{name}</a>
      ),
    },
    {
      title: '交接状态',
      dataIndex: 'handoverStatus',
      key: 'handoverStatus',
      width: 120,
      sorter: (a: CustomerHandover, b: CustomerHandover) => a.handoverStatus.localeCompare(b.handoverStatus),
      render: (status: string, record: CustomerHandover) => {
        const statusMap = {
          pending_handover: { text: '待交接', color: 'orange' },
          handover_in_progress: { text: '交接中', color: 'blue' },
          pending_implementation: { text: '待实施', color: 'purple' },
          implementation_in_progress: { text: '实施中', color: 'green' }
        };
        const config = statusMap[status as keyof typeof statusMap] || { text: status, color: 'default' };
        return (
          <Tag color={config.color} style={{ cursor: 'pointer' }} onClick={() => handleViewDetail(record, 'action-plan')}>
            {config.text}
          </Tag>
        );
      },
    },
    // 隐藏风险提示列
    // {
    //   title: '风险提示',
    //   dataIndex: 'hasRiskAlert',
    //   key: 'hasRiskAlert',
    //   width: 100,
    //   sorter: (a: CustomerHandover, b: CustomerHandover) => Number(a.hasRiskAlert) - Number(b.hasRiskAlert),
    //   render: (hasRisk: boolean, record: CustomerHandover) => {
    //     if (!hasRisk) return <Tag>无风险</Tag>;
    //     const level = record.riskLevel;
    //     const color = riskColorMap[level as keyof typeof riskColorMap] || 'orange';
    //     const text = riskTextMap[level as keyof typeof riskTextMap] || '有风险';
    //     return (
    //       <Tag color={color} style={{ cursor: 'pointer' }} onClick={() => handleViewDetail(record, 'risks-opportunities')}>
    //         {text}
    //       </Tag>
    //     );
    //   },
    // },
    {
      title: '干系人',
      dataIndex: 'stakeholderCount',
      key: 'stakeholderCount',
      width: 80,
      sorter: (a: CustomerHandover, b: CustomerHandover) => (a.stakeholderCount || 0) - (b.stakeholderCount || 0),
      render: (count: number, record: CustomerHandover) => (
        <Tag color="purple" style={{ cursor: 'pointer' }} onClick={() => handleViewDetail(record, 'stakeholders')}>
          {count} 人
        </Tag>
      ),
    },
    {
      title: '客户期望对齐',
      dataIndex: 'expectationAlignment',
      key: 'expectationAlignment',
      width: 120,
      sorter: (a: CustomerHandover, b: CustomerHandover) => a.expectationAlignment.localeCompare(b.expectationAlignment),
      render: (alignment: string, record: CustomerHandover) => {
        const colorMap = {
          aligned: 'green',
          partially_aligned: 'gold',
          not_aligned: 'red'
        };
        const textMap = {
          aligned: '已对齐',
          partially_aligned: '部分对齐',
          not_aligned: '未对齐'
        };
        return (
          <Tag color={colorMap[alignment as keyof typeof colorMap]} style={{ cursor: 'pointer' }} onClick={() => handleViewDetail(record, 'expectation-alignment')}>
            {textMap[alignment as keyof typeof textMap]}
          </Tag>
        );
      },
    },
    {
      title: '销售创建时间',
      dataIndex: 'salesCreatedAt',
      key: 'salesCreatedAt',
      width: 120,
      sorter: (a: CustomerHandover, b: CustomerHandover) => new Date(a.salesCreatedAt || '').getTime() - new Date(b.salesCreatedAt || '').getTime(),
      render: (date: string) => date ? new Date(date).toLocaleDateString() : '-',
    },
    // {
    //   title: '客户满意度',
    //   dataIndex: 'handoverRating',
    //   key: 'handoverRating',
    //   width: 150,
    //   sorter: (a: CustomerHandover, b: CustomerHandover) => (a.handoverRating || 0) - (b.handoverRating || 0),
    //   render: (rating: number, record: CustomerHandover) => (
    //     <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
    //       <Rate 
    //         disabled 
    //         value={rating} 
    //         style={{ fontSize: '16px' }}
    //       />
    //       <span style={{ color: '#1890ff', fontWeight: '500' }}>
    //         {rating}
    //       </span>
    //     </div>
    //   ),
    // },
  ];

  return (
    <div style={{ 
      padding: '32px 40px',
      background: '#f5f5f5',
      minHeight: 'calc(100vh - 64px)'
    }}>
      {/* 页面标题 */}
          <div style={{ 
            display: 'flex', 
            justifyContent: 'space-between', 
