// 迷你趋势图组件
const Sparkline: React.FC<{ data: number[]; color?: string }> = ({ data, color = '#52c41a' }) => {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  const points = data.map((value, index) => {
    const x = (index / (data.length - 1)) * 60;
    const y = 20 - ((value - min) / range) * 16;
    return `${x},${y}`;
  }).join(' ');

  // 判断趋势方向
  const isUpward = data[data.length - 1] > data[0];
  const isDownward = data[data.length - 1] < data[0];
  const trendColor = isDownward ? '#fa541c' : isUpward ? '#52c41a' : '#8c8c8c';

  return (
    <svg width="60" height="20" style={{ marginTop: '4px' }}>
      <polyline
        points={points}
        fill="none"
        stroke={trendColor}
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      {/* 添加小圆点标记最新值 */}
      <circle
        cx={60}
        cy={20 - ((data[data.length - 1] - min) / range) * 16}
        r="1.5"
        fill={trendColor}
      />
    </svg>
  );
};

// 关键任务组件
const KeyTaskComponent: React.FC<{ 
  task: Task; 
  onTaskClick: (task: Task) => void;
  onEditTask: (task: Task) => void;
}> = ({ task, onTaskClick, onEditTask }) => {
  const getStatusIcon = () => {
    switch (task.status) {
      case 'completed':
        return <CheckCircleOutlined style={{ color: '#52c41a' }} />;
      case 'in_progress':
        return <ClockCircleOutlined style={{ color: '#1890ff' }} />;
      default:
        return <div style={{ 
          width: '14px', 
          height: '14px', 
          border: '2px solid #d9d9d9', 
          borderRadius: '2px',
          cursor: 'pointer'
        }} />;
    }
  };

  const getPriorityColor = () => {
    switch (task.priority) {
      case 'high': return '#fa541c';
      case 'medium': return '#faad14';
      default: return '#52c41a';
    }
  };

  const isOverdue = new Date(task.dueDate) < new Date() && task.status !== 'completed';

  return (
    <div 
      style={{
        border: '1px solid #f0f0f0',
        borderRadius: '6px',
        padding: '8px 10px',
        background: '#fafafa',
        cursor: 'pointer',
        transition: 'all 0.2s',
        position: 'relative'
      }}
      onClick={() => onTaskClick(task)}
      onMouseEnter={(e) => {
        e.currentTarget.style.borderColor = '#1890ff';
        e.currentTarget.style.background = '#f6f9ff';
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.borderColor = '#f0f0f0';
        e.currentTarget.style.background = '#fafafa';
      }}
    >
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: '8px' }}>
        <div style={{ marginTop: '2px' }}>
          {getStatusIcon()}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ 
            fontSize: '13px', 
            fontWeight: 500, 
            color: '#262626',
            marginBottom: '4px',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap'
          }}>
            {task.title}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Avatar size={16} style={{ backgroundColor: getPriorityColor(), fontSize: '10px' }}>
              {task.assignee.charAt(0)}
            </Avatar>
            <span style={{ 
              fontSize: '11px', 
              color: isOverdue ? '#fa541c' : '#8c8c8c'
            }}>
              {task.dueDate}
            </span>
          </div>
        </div>
        <Button 
          type="text" 
          size="small" 
          icon={<EditOutlined />}
          style={{ 
            padding: '2px 4px', 
            height: 'auto',
            minWidth: 'auto',
            opacity: 0.6
          }}
          onClick={(e) => {
            e.stopPropagation();
            onEditTask(task);
          }}
        />
      </div>
      {task.priority === 'high' && (
        <div style={{
          position: 'absolute',
          top: '4px',
          right: '4px',
          width: '6px',
          height: '6px',
          borderRadius: '50%',
          background: '#fa541c'
        }} />
      )}
    </div>
  );
