import React, { useState } from 'react';
import {
  Card,
  Row,
  Col,
  Statistic,
  Table,
  Button,
  Input,
  Select,
  DatePicker,
  Tag,
  Space,
  Modal,
  Form,
  message,
  Tabs,
  Progress,
  Avatar,
  List,
  Badge,
  Tooltip,
  Typography,
} from 'antd';
import {
  MessageOutlined,
  UserOutlined,
  BellOutlined,
  LikeOutlined,
  CommentOutlined,
  ShareAltOutlined,
  PlusOutlined,
  SearchOutlined,
  FilterOutlined,
  ExportOutlined,
  EyeOutlined,
  EditOutlined,
  DeleteOutlined,
  QuestionCircleOutlined,
  ArrowUpOutlined,
  ArrowDownOutlined,
  BarChartOutlined,
  SendOutlined,
} from '@ant-design/icons';
import { Column } from '@ant-design/charts';
import type { ColumnsType } from 'antd/es/table';

const { Search } = Input;
const { Option } = Select;
const { RangePicker } = DatePicker;
const { TextArea } = Input;
const { TabPane } = Tabs;
const { Title, Text } = Typography;

// 统一的卡片样式 - 参考持续服务的现代风格
const cardStyle = {
  borderRadius: '12px',
  boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06)',
  border: '1px solid #f0f0f0',
  background: '#ffffff',
  marginBottom: '16px',
};

interface FeedbackRecord {
  id: string;
  customerName: string;
  company: string;
  feedbackType: 'bug' | 'feature' | 'complaint' | 'suggestion';
  content: string;
  status: 'pending' | 'processing' | 'resolved' | 'closed';
  priority: 'high' | 'medium' | 'low';
  createTime: string;
  assignee?: string;
}

interface ActivityRecord {
  id: string;
  title: string;
  type: 'announcement' | 'event' | 'promotion' | 'training';
  targetAudience: string;
  status: 'draft' | 'published' | 'ended';
  participantCount: number;
  engagementRate: number;
  createTime: string;
}

interface InteractionData {
  month: string;
  feedback: number;
  activities: number;
  engagement: number;
}

const UserInteractionManagement: React.FC = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [feedbackModalVisible, setFeedbackModalVisible] = useState(false);
  const [activityModalVisible, setActivityModalVisible] = useState(false);
  const [selectedFeedback, setSelectedFeedback] = useState<FeedbackRecord | null>(null);

  // 模拟数据
  const interactionData: InteractionData[] = [
    { month: '1月', feedback: 45, activities: 8, engagement: 78 },
    { month: '2月', feedback: 52, activities: 12, engagement: 82 },
    { month: '3月', feedback: 38, activities: 15, engagement: 85 },
    { month: '4月', feedback: 61, activities: 10, engagement: 79 },
    { month: '5月', feedback: 49, activities: 18, engagement: 88 },
    { month: '6月', feedback: 55, activities: 14, engagement: 91 },
  ];

  const feedbackData: FeedbackRecord[] = [
    {
      id: '1',
      customerName: '张经理',
      company: '科技有限公司',
      feedbackType: 'feature',
      content: '希望能增加批量导入学员功能',
      status: 'processing',
      priority: 'high',
      createTime: '2024-01-15 10:30',
      assignee: '李产品',
    },
    {
      id: '2',
      customerName: '王总监',
      company: '教育集团',
      feedbackType: 'bug',
      content: '数据导出功能偶尔会出现卡顿',
      status: 'resolved',
      priority: 'medium',
      createTime: '2024-01-14 14:20',
      assignee: '赵开发',
    },
    {
      id: '3',
      customerName: '刘主任',
      company: '培训机构',
      feedbackType: 'complaint',
      content: '系统响应速度较慢，影响使用体验',
      status: 'pending',
      priority: 'high',
      createTime: '2024-01-13 16:45',
    },
  ];

  const activityData: ActivityRecord[] = [
    {
      id: '1',
      title: '授客SaaS 2.0版本发布会',
      type: 'announcement',
      targetAudience: '全部客户',
      status: 'published',
      participantCount: 156,
      engagementRate: 78.5,
      createTime: '2024-01-10',
    },
    {
      id: '2',
      title: '客户成功最佳实践分享',
      type: 'training',
      targetAudience: '企业客户',
      status: 'published',
      participantCount: 89,
      engagementRate: 85.2,
      createTime: '2024-01-08',
    },
    {
      id: '3',
      title: '春节特惠活动',
      type: 'promotion',
      targetAudience: '潜在客户',
      status: 'ended',
      participantCount: 234,
      engagementRate: 92.1,
      createTime: '2024-01-05',
    },
  ];

  const feedbackColumns: ColumnsType<FeedbackRecord> = [
    {
      title: '客户信息',
      key: 'customer',
      render: (record: FeedbackRecord) => (
        <div>
          <div style={{ fontWeight: 'bold' }}>{record.customerName}</div>
          <div style={{ color: '#666', fontSize: '12px' }}>{record.company}</div>
        </div>
      ),
    },
    {
      title: '反馈类型',
      dataIndex: 'feedbackType',
      key: 'feedbackType',
      render: (type: string) => {
        const typeMap = {
          bug: { color: 'red', text: 'Bug反馈' },
          feature: { color: 'blue', text: '功能建议' },
          complaint: { color: 'orange', text: '投诉建议' },
          suggestion: { color: 'green', text: '优化建议' },
        };
        const config = typeMap[type as keyof typeof typeMap];
        return <Tag color={config.color}>{config.text}</Tag>;
