            rules={[{ required: true, message: '请选择到期时间' }]}
          >
            <DatePicker style={{ width: '100%' }} placeholder="请选择到期时间" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default EnterpriseManagement;

